export async function createServer() {
  const fastify = Fastify({
    logger: process.env.NODE_ENV === 'production'
      ? {
          level: process.env.LOG_LEVEL || 'info',
          transport: {
            targets: [
              // Console output (for Docker, PM2, systemd)
              {
                target: 'pino/file',
                options: { destination: 1 }, // stdout
                level: 'info'
              },
              // File output
              {
                target: 'pino/file',
                options: {
                  destination: process.env.LOG_FILE || './logs/app.log',
                  mkdir: true
                },
                level: process.env.LOG_LEVEL || 'info'
              }
            ]
          }
        }
      : {
          // Development: pretty-print to console + log file
          level: process.env.LOG_LEVEL || 'info',
          transport: {
            targets: [
              // Pretty console output
              {
                target: 'pino-pretty',
                options: {
                  colorize: true,
                  translateTime: 'HH:MM:ss Z',
                  ignore: 'pid,hostname'
                },
                level: process.env.LOG_LEVEL || 'info'
              },
              // File output (plain JSON)
              {
                target: 'pino/file',
                options: {
                  destination: process.env.LOG_FILE || './logs/app.log',
                  mkdir: true
                },
                level: process.env.LOG_LEVEL || 'info'
              }
            ]
          }
        }
  }).withTypeProvider<ZodTypeProvider>();

  // Intercept console.log/error/warn and redirect to Pino logger
  // This captures console.log calls from dependencies like agent-cli-sdk
  const originalConsoleLog = console.log;
  const originalConsoleError = console.error;
  const originalConsoleWarn = console.warn;

  console.log = (...args: unknown[]) => {
    const message = args.map(arg =>
      typeof arg === 'object' ? JSON.stringify(arg) : String(arg)
    ).join(' ');
    fastify.log.info(message);
  };

  console.error = (...args: unknown[]) => {
    const message = args.map(arg =>
      typeof arg === 'object' ? JSON.stringify(arg) : String(arg)
    ).join(' ');
    fastify.log.error(message);
  };

  console.warn = (...args: unknown[]) => {
    const message = args.map(arg =>
      typeof arg === 'object' ? JSON.stringify(arg) : String(arg)
    ).join(' ');
    fastify.log.warn(message);
  };

  // Store originals for potential restoration
  (fastify as typeof fastify & { _originalConsole?: typeof console }).._originalConsole = {
    log: originalConsoleLog,
    error: originalConsoleError,
    warn: originalConsoleWarn,
  };

